create table if not exists mobile_auth_flows(id uuid primary key default gen_random_uuid(),challenge text not null check(challenge~'^[a-f0-9]{64}$'),next_path text not null,intent text not null,session_encrypted text,expires_at timestamptz not null default now()+interval '5 minutes',consumed_at timestamptz,created_at timestamptz default now());
alter table mobile_auth_flows enable row level security;revoke all on mobile_auth_flows from anon,authenticated;grant all on mobile_auth_flows to service_role;
create or replace function reloo_complete_mobile_auth(p_id uuid,p_session text) returns void language plpgsql security definer set search_path=public as $$begin update mobile_auth_flows set session_encrypted=p_session where id=p_id and expires_at>now() and consumed_at is null and session_encrypted is null;if not found then raise exception 'MOBILE_FLOW_EXPIRED';end if;end$$;
create or replace function reloo_consume_mobile_auth(p_id uuid,p_challenge text) returns jsonb language plpgsql security definer set search_path=public as $$declare item mobile_auth_flows;begin select * into item from mobile_auth_flows where id=p_id and challenge=p_challenge and expires_at>now() and consumed_at is null and session_encrypted is not null for update;if not found then raise exception 'MOBILE_FLOW_INVALID';end if;update mobile_auth_flows set consumed_at=now(),session_encrypted=null where id=p_id;return jsonb_build_object('session',item.session_encrypted,'next',item.next_path);end$$;
revoke all on function reloo_complete_mobile_auth(uuid,text),reloo_consume_mobile_auth(uuid,text) from public,anon,authenticated;grant execute on function reloo_complete_mobile_auth(uuid,text),reloo_consume_mobile_auth(uuid,text) to service_role;
notify pgrst,'reload schema';
